 "content": "def transform(grid):
    # The grid contains separated 3x3 colored tiles. Return the unique tile
    # containing exactly three distinct non-background colors.
    h, w = len(grid), len(grid[0])
    occupied = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not occupied:
        return []
    rmin = min(r for r, _ in occupied)
    rmax = max(r for r, _ in occupied)
    cmin = min(c for _, c in occupied)
    cmax = max(c for _, c in occupied)
    candidates = []
    for r in range(rmin, rmax - 1):
        for c in range(cmin, cmax - 1):
            tile = [row[c:c+3] for row in grid[r:r+3]]
            if len(tile) == 3 and all(len(row) == 3 for row in tile) and all(v != 0 for row in tile for v in row):
                if len(set(v for row in tile for v in row)) == 3:
                    candidates.append(tile)
    if len(candidates) != 1:
        raise ValueError(f"Expected one three-color tile, found {len(candidates)}")
    return candidates[0]
